public int gemstones(String[] rocks) {
    int gems = 0;
    for (char c = 'a'; c <= 'z'; c++) {
        boolean inAll = true;
        for (String rock : rocks) {
            if (rock.indexOf(c) == -1) {
                inAll = false;
                break;
            }
        }
        if (inAll) {
            gems++;
        }
    }
    return gems;
}

