public int gemstones(String[] rocks) {
    int[] rockCount = new int[26];
    for (String rock : rocks) {
        boolean[] seen = new boolean[26];
        for (int i = 0; i < rock.length(); i++) {
            seen[rock.charAt(i) - 'a'] = true;
        }
        for (int c = 0; c < 26; c++) {
            if (seen[c]) {
                rockCount[c]++;
            }
        }
    }
    int gems = 0;
    for (int c = 0; c < 26; c++) {
        if (rockCount[c] == rocks.length) {
            gems++;
        }
    }
    return gems;
}

